DROP TABLE IF EXISTS `k1_ik_bordrolar`;
CREATE TABLE `k1_ik_bordrolar` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `kullanici_id` int(11) NOT NULL, `yil` smallint(6) NOT NULL, `ay` tinyint(4) NOT NULL, `brut` decimal(12,2) NOT NULL DEFAULT 0.00, `net` decimal(12,2) NOT NULL DEFAULT 0.00, `kesinti` decimal(12,2) NOT NULL DEFAULT 0.00, `dosya` varchar(255) NOT NULL DEFAULT '', `orijinal_ad` varchar(255) NOT NULL DEFAULT '', `ekleyen_id` int(11) DEFAULT NULL, `tarih` datetime NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (`id`), UNIQUE KEY `uq_bordro` (`kullanici_id`,`yil`,`ay`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_dosya_indirme`;
CREATE TABLE `k1_ik_dosya_indirme` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `dosya_id` int(10) unsigned NOT NULL, `kullanici_id` int(11) NOT NULL, `zaman` datetime NOT NULL, PRIMARY KEY (`id`), KEY `ix_di_dosya` (`dosya_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_dosyalar`;
CREATE TABLE `k1_ik_dosyalar` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `ad` varchar(200) NOT NULL, `aciklama` varchar(500) NOT NULL DEFAULT '', `klasor` varchar(80) NOT NULL DEFAULT '', `dosya` varchar(120) NOT NULL, `orijinal_ad` varchar(255) NOT NULL DEFAULT '', `mime` varchar(120) NOT NULL DEFAULT '', `boyut` int(10) unsigned NOT NULL DEFAULT 0, `hedef_tip` varchar(8) NOT NULL DEFAULT 'herkes', `hedef_birim` text DEFAULT NULL, `hedef_kisi` text DEFAULT NULL, `indirme_tip` varchar(8) NOT NULL DEFAULT 'gorenler', `indirme_kisi` text DEFAULT NULL, `duyuru_id` int(10) unsigned DEFAULT NULL, `yukleyen_id` int(11) NOT NULL DEFAULT 0, `tarih` datetime DEFAULT NULL, `indirme_say` int(10) unsigned NOT NULL DEFAULT 0, PRIMARY KEY (`id`), KEY `ix_df_duyuru` (`duyuru_id`), KEY `ix_df_klasor` (`klasor`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_duyurular`;
CREATE TABLE `k1_ik_duyurular` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `baslik` varchar(200) NOT NULL, `icerik` mediumtext DEFAULT NULL, `tur` varchar(12) NOT NULL DEFAULT 'genel', `sabit` tinyint(1) NOT NULL DEFAULT 0, `hedef_tip` varchar(8) NOT NULL DEFAULT 'herkes', `hedef_birim` text DEFAULT NULL, `hedef_kisi` text DEFAULT NULL, `durum` varchar(10) NOT NULL DEFAULT 'yayinda', `onay_iste` tinyint(1) NOT NULL DEFAULT 0, `bitis` date DEFAULT NULL, `olusturan_id` int(11) NOT NULL DEFAULT 0, `olusturma` datetime DEFAULT NULL, `guncelleme` datetime DEFAULT NULL, `yayin` datetime DEFAULT NULL, PRIMARY KEY (`id`), KEY `ix_dy_durum` (`durum`,`sabit`,`yayin`) ) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_egitim_bildirim_log`;
CREATE TABLE `k1_ik_egitim_bildirim_log` ( `egitim_id` int(10) unsigned NOT NULL, `kullanici_id` int(11) NOT NULL, `anahtar` varchar(40) NOT NULL, `zaman` datetime NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (`egitim_id`,`kullanici_id`,`anahtar`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_egitim_katilim`;
CREATE TABLE `k1_ik_egitim_katilim` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `egitim_id` int(10) unsigned NOT NULL, `kullanici_id` int(11) NOT NULL, `tamamlandi` tinyint(1) NOT NULL DEFAULT 0, PRIMARY KEY (`id`), UNIQUE KEY `uq_egitim_kisi` (`egitim_id`,`kullanici_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_egitimler`;
