DROP TABLE IF EXISTS `k1_ik_masraflar`;
CREATE TABLE `k1_ik_masraflar` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `kullanici_id` int(11) NOT NULL, `kategori` varchar(60) NOT NULL DEFAULT 'diger', `tutar` decimal(12,2) NOT NULL DEFAULT 0.00, `tarih` date NOT NULL, `aciklama` varchar(500) NOT NULL DEFAULT '', `durum` varchar(20) NOT NULL DEFAULT 'beklemede', `onaylayan_id` int(11) DEFAULT NULL, `onay_notu` varchar(500) NOT NULL DEFAULT '', `onay_tarihi` datetime DEFAULT NULL, `olusturma_tarihi` datetime NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (`id`), KEY `ix_masraf_kisi` (`kullanici_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_mesailer`;
CREATE TABLE `k1_ik_mesailer` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `kullanici_id` int(11) NOT NULL, `tarih` date NOT NULL, `baslangic` char(5) NOT NULL DEFAULT '', `bitis` char(5) NOT NULL DEFAULT '', `dakika` int(11) NOT NULL DEFAULT 0, `tur` varchar(12) NOT NULL DEFAULT 'normal', `tatil_adi` varchar(100) NOT NULL DEFAULT '', `aciklama` varchar(300) NOT NULL DEFAULT '', `durum` varchar(12) NOT NULL DEFAULT 'onaylandi', `giren_id` int(11) DEFAULT NULL, `karar_veren_id` int(11) DEFAULT NULL, `karar_tarihi` datetime DEFAULT NULL, `olusturma` datetime NOT NULL DEFAULT current_timestamp(), PRIMARY KEY (`id`), KEY `ix_mesai_kisi` (`kullanici_id`,`tarih`), KEY `ix_mesai_tarih` (`tarih`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_notlar`;
CREATE TABLE `k1_ik_notlar` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `tarih` date NOT NULL, `saat` varchar(5) NOT NULL DEFAULT '', `baslik` varchar(160) NOT NULL DEFAULT '', `icerik` varchar(2000) NOT NULL DEFAULT '', `renk` varchar(9) NOT NULL DEFAULT '#6366f1', `kullanici_id` int(10) unsigned NOT NULL DEFAULT 0, `herkese` tinyint(1) NOT NULL DEFAULT 0, `hatirlat` tinyint(1) NOT NULL DEFAULT 1, `gun1_gonderildi` tinyint(1) NOT NULL DEFAULT 0, `gun0_gonderildi` tinyint(1) NOT NULL DEFAULT 0, `olusturma` datetime NOT NULL, PRIMARY KEY (`id`), KEY `k_tarih` (`tarih`), KEY `k_kul` (`kullanici_id`) ) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `k1_ik_okumalar`;
CREATE TABLE `k1_ik_okumalar` ( `tip` varchar(10) NOT NULL, `oge_id` int(10) unsigned NOT NULL, `kullanici_id` int(11) NOT NULL, `zaman` datetime NOT NULL, `onay` tinyint(1) NOT NULL DEFAULT 0, PRIMARY KEY (`tip`,`oge_id`,`kullanici_id`), KEY `ix_ok_kisi` (`kullanici_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TABLE IF EXISTS `k1_ik_onay_akis`;
CREATE TABLE `k1_ik_onay_akis` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `departman` varchar(100) NOT NULL, `sira` tinyint(4) NOT NULL DEFAULT 1, `onaylayici_id` int(11) NOT NULL DEFAULT 0, `k_site` tinyint(1) NOT NULL DEFAULT 1, `k_sms` tinyint(1) NOT NULL DEFAULT 0, `k_mail` tinyint(1) NOT NULL DEFAULT 0, `vekil_id` int(11) NOT NULL DEFAULT 0, PRIMARY KEY (`id`), KEY `ix_akis_dep` (`departman`,`sira`) ) ENGINE=InnoDB AUTO_INCREMENT=94 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
