DROP TABLE IF EXISTS `k1_ik_perf_atama`;
CREATE TABLE `k1_ik_perf_atama` ( `id` int(10) unsigned NOT NULL AUTO_INCREMENT, `surec_id` int(10) unsigned NOT NULL, `hedef_id` int(10) unsigned NOT NULL, `degerlendiren_id` int(10) unsigned NOT NULL, `iliski` varchar(8) NOT NULL DEFAULT 'amir', `durum` varchar(10) NOT NULL DEFAULT 'bekliyor', `yanitlar` mediumtext DEFAULT NULL, `yorum` varchar(2000) NOT NULL DEFAULT '', `puan` decimal(4,2) DEFAULT NULL, `tamam_tarih` datetime DEFAULT NULL, `son_hatirlatma` datetime DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `u_a` (`surec_id`,`hedef_id`,`degerlendiren_id`), KEY `k_deg` (`degerlendiren_id`,`durum`), KEY `k_hedef` (`hedef_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `k1_ik_perf_hedef`;
